fn delete_key_value_inductive(pre: Self, post: Self, key: Key, row: Row, col: Col) {
    // Proof that key_in_map_implies_key_in_matrix holds after deletion
    assert forall |k| #[trigger] post.frag[k].is_some() implies
        exists |r: int, c: int|
            0 <= r < HEIGHT && 0 <= c < WIDTH
                && #[trigger] post.matrix[r as nat][c as int].is_some()
                && #[trigger] post.matrix[r as nat][c as int].unwrap().0 == k
    by {
        if k == key {
            // The key was deleted, so post.frag[key] should be None
            assert(post.frag[k] === None);
        } else {
            // For other keys, the property still holds from pre-state
            assert(pre.frag[k].is_some());
            // By pre invariant, there exists a position for k in pre matrix
            assert(exists |r0: int, c0: int|
                0 <= r0 < HEIGHT && 0 <= c0 < WIDTH
                    && #[trigger] pre.matrix[r0 as nat][c0 as int].is_some()
                    && #[trigger] pre.matrix[r0 as nat][c0 as int].unwrap().0 == k);

            // If the position wasn't affected by the deletion, it still exists in post
            if !(row < HEIGHT && col < WIDTH && pre.matrix[row][col as int].is_some() 
                && pre.matrix[row][col as int].unwrap().0 == k) {
                // The position for k is unchanged
                let (r0, c0) = choose |r0: int, c0: int|
                    0 <= r0 < HEIGHT && 0 <= c0 < WIDTH
                        && #[trigger] pre.matrix[r0 as nat][c0 as int].is_some()
                        && #[trigger] pre.matrix[r0 as nat][c0 as int].unwrap().0 == k;
                assert(post.matrix[r0 as nat][c0 as int].is_some() && post.matrix[r0 as nat][c0 as int].unwrap().0 == k);
            } else {
                // This case shouldn't happen as we assumed k != key
                assert(false);
            }
        }
    }

    // Proof that pair_in_matrix_implies_pair_in_map holds after deletion
    assert forall |r: int, c: int|
        0 <= r < HEIGHT ==>
        0 <= c < WIDTH ==>
        #[trigger] post.matrix[r as nat][c as int].is_some() ==>
        #[trigger] post.frag[post.matrix[r as nat][c as int].unwrap().0]
            == Some(post.matrix[r as nat][c as int].unwrap().1)
    by {
        // Precondition: post.matrix[r as nat][c as int].is_some()
        // Goal: post.frag[post.matrix[r as nat][c as int].unwrap().0] == Some(post.matrix[r as nat][c as int].unwrap().1)

        // Since we deleted at (row, col), if (r, c) != (row, col), then matrix[r][c] is unchanged
        if r == row && c == col {
            // This position was deleted, so it should be None in post
            assert(post.matrix[r as nat][c as int].is_none());
            // The precondition says it's some, but we just showed it's none - contradiction
            assert(false);
        } else {
            // Position is unchanged from pre to post
            assert(pre.matrix[r as nat][c as int] == post.matrix[r as nat][c as int]);
            // By pre invariant
            assert(pre.frag[pre.matrix[r as nat][c as int].unwrap().0]
                == Some(pre.matrix[r as nat][c as int].unwrap().1));
            // Since matrix[r][c] is unchanged, frag must also be unchanged for this key
            assert(post.frag[post.matrix[r as nat][c as int].unwrap().0]
                == Some(post.matrix[r as nat][c as int].unwrap().1));
        }
    }
}

